from taf.nms.nom.schemas.base import SchemaObject, SchemaField


class Alarm(SchemaObject):
    alarm_status = SchemaField(name="alarm_status")
    system_alarm_id = SchemaField(name="system_alarm_id")
    dn = SchemaField(name="dn")
    integrated_id = SchemaField(name="integrated_id")
    first_notification_time = SchemaField(name="first_notification_time")
    last_update_notification_time = SchemaField(name="last_update_notification_time")
    clear_time = SchemaField(name="clear_time")
    ack_time = SchemaField(name="ack_time")
    specific_problem = SchemaField(name="specific_problem")
    alarm_type = SchemaField(name="alarm_type")
    probable_cause = SchemaField(name="probable_cause")
    probable_cause_code = SchemaField(name="probable_cause_code")
    alarm_text = SchemaField(name="alarm_text")
    additional_alarm_text1 = SchemaField(name="additional_alarm_text1")
    additional_alarm_text2 = SchemaField(name="additional_alarm_text2")
    additional_alarm_text3 = SchemaField(name="additional_alarm_text3")
    additional_alarm_text4 = SchemaField(name="additional_alarm_text4")
    additional_alarm_text5 = SchemaField(name="additional_alarm_text5")
    additional_alarm_text6 = SchemaField(name="additional_alarm_text6")
    additional_alarm_text7 = SchemaField(name="additional_alarm_text7")
    severity = SchemaField(name="severity")
    ack_status = SchemaField(name="ack_status")
    ack_user = SchemaField(name="ack_user")
    clear_user = SchemaField(name="clear_user")
    system_dn = SchemaField(name="system_dn")
    additional_information = SchemaField(name="additional_information")

    def __init__(self, alarm_status, system_alarm_id, dn, integrated_id, first_notification_time, last_update_notification_time,
                 clear_time, ack_time, specific_problem, alarm_type, probable_cause, probable_cause_code, alarm_text,
                 additional_alarm_text1, additional_alarm_text2, additional_alarm_text3, additional_alarm_text4,
                 additional_alarm_text5, additional_alarm_text6, additional_alarm_text7,
                 severity, ack_status, ack_user, clear_user, system_dn, additional_information):
        self.alarm_status = alarm_status
        self.system_alarm_id = system_alarm_id
        self.integrated_id = integrated_id
        self.dn = dn
        self.first_notification_time = first_notification_time
        self.last_update_notification_time = last_update_notification_time
        self.clear_time = clear_time
        self.ack_time = ack_time
        self.specific_problem = specific_problem
        self.alarm_type = alarm_type
        self.probable_cause = probable_cause
        self.probable_cause_code = probable_cause_code
        self.alarm_text = alarm_text
        self.additional_alarm_text1 = additional_alarm_text1
        self.additional_alarm_text2 = additional_alarm_text2
        self.additional_alarm_text3 = additional_alarm_text3
        self.additional_alarm_text4 = additional_alarm_text4
        self.additional_alarm_text5 = additional_alarm_text5
        self.additional_alarm_text6 = additional_alarm_text6
        self.additional_alarm_text7 = additional_alarm_text7
        self.severity = severity
        self.ack_status = ack_status
        self.ack_user = ack_user
        self.clear_user = clear_user
        self.system_dn = system_dn
        self.additional_information = additional_information

        super(Alarm, self).__init__()
